import Mathlib

open BigOperators Finset
open Topology

variable {N : ℕ}

def HasExpectedUtilityForm (U : (Fin N → ℝ) → ℝ) : Prop :=
  ∃ u : Fin N → ℝ, ∀ p : Fin N → ℝ, U p = ∑ n : Fin N, p n * u n

import Mathlib

def MoreRiskAverse (u₁ u₂ : ℝ → ℝ) : Prop :=
  ∃ g : ℝ → ℝ, ConcaveOn ℝ Set.univ g ∧ ∀ x, u₂ x = g (u₁ x)
